let data = msg.payload;

// Validación mínima
if (!data.parcel || !data.crop || !data.sensor || data.value === undefined) {
    node.warn("Dato inválido para InfluxDB");
    return null;
}

let numericValue = Number(data.value);

if (isNaN(numericValue)) {
    node.warn("Dato inválido: value no es numérico");
    return null;
}

// Función para clasificar el tipo de alerta
function getAlertInfo(crop, sensor, value) {
    let alertType = "none";
    let alertDescription = "Sin alerta";
    let alertLevel = "normal";

    if (crop === "rice") {
        if (sensor === "temperature") {
            if (value < 20) {
                alertType = "low_temperature";
                alertDescription = "Arroz con temperatura baja";
                alertLevel = "critical";
            } else if (value > 35) {
                alertType = "high_temperature";
                alertDescription = "Arroz con temperatura alta";
                alertLevel = "critical";
            }
        }

        if (sensor === "humidity") {
            if (value < 55) {
                alertType = "low_humidity";
                alertDescription = "Arroz con humedad baja";
                alertLevel = "critical";
            } else if (value > 95) {
                alertType = "high_humidity";
                alertDescription = "Arroz con humedad alta";
                alertLevel = "critical";
            }
        }

        if (sensor === "rainfall") {
            if (value < 2) {
                alertType = "low_rainfall";
                alertDescription = "Arroz con baja precipitación";
                alertLevel = "critical";
            } else if (value > 70) {
                alertType = "high_rainfall";
                alertDescription = "Arroz con exceso de precipitación";
                alertLevel = "critical";
            }
        }

        if (sensor === "solar_radiation") {
            if (value < 250) {
                alertType = "low_solar_radiation";
                alertDescription = "Arroz con baja radiación solar";
                alertLevel = "critical";
            }
        }

        if (sensor === "soil_ph") {
            if (value < 5.5) {
                alertType = "low_soil_ph";
                alertDescription = "Arroz con pH del suelo bajo";
                alertLevel = "critical";
            } else if (value > 7.5) {
                alertType = "high_soil_ph";
                alertDescription = "Arroz con pH del suelo alto";
                alertLevel = "critical";
            }
        }
    }

    if (crop === "sugar_cane") {
        if (sensor === "temperature") {
            if (value < 18) {
                alertType = "low_temperature";
                alertDescription = "Caña de azúcar con temperatura baja";
                alertLevel = "critical";
            } else if (value > 35) {
                alertType = "high_temperature";
                alertDescription = "Caña de azúcar con temperatura alta";
                alertLevel = "critical";
            }
        }

        if (sensor === "humidity") {
            if (value < 50) {
                alertType = "low_humidity";
                alertDescription = "Caña de azúcar con humedad baja";
                alertLevel = "critical";
            } else if (value > 92) {
                alertType = "high_humidity";
                alertDescription = "Caña de azúcar con humedad alta";
                alertLevel = "critical";
            }
        }

        if (sensor === "solar_radiation") {
            if (value < 250) {
                alertType = "low_solar_radiation";
                alertDescription = "Caña de azúcar con baja radiación solar";
                alertLevel = "critical";
            }
        }

        if (sensor === "soil_ph") {
            if (value < 5.5) {
                alertType = "low_soil_ph";
                alertDescription = "Caña de azúcar con pH del suelo bajo";
                alertLevel = "critical";
            } else if (value > 7.5) {
                alertType = "high_soil_ph";
                alertDescription = "Caña de azúcar con pH del suelo alto";
                alertLevel = "critical";
            }
        }

        if (sensor === "wind_speed") {
            if (value > 20) {
                alertType = "high_wind_speed";
                alertDescription = "Caña de azúcar con velocidad de viento elevada";
                alertLevel = "critical";
            }
        }
    }

    return {
        alertType,
        alertDescription,
        alertLevel
    };
}

let alertInfo = getAlertInfo(
    String(data.crop),
    String(data.sensor),
    numericValue
);

// Fields: valores numéricos guardados como datos
let fields = {
    value: numericValue,
    alert: data.alert ? 1 : 0,
    sampling_interval_seconds: Number(data.sampling_interval_seconds)
};

// Tags: sirven para filtrar en InfluxDB y Grafana
let tags = {
    parcel: String(data.parcel),
    crop: String(data.crop),
    zone: String(data.zone),
    sensor: String(data.sensor),
    sensor_type: String(data.sensor_type),
    condition: String(data.condition),
    simulator: String(data.simulator),
    status: String(data.status),
    unit: String(data.unit),

    // Nuevos tags para el historial de alertas
    alert_type: String(alertInfo.alertType),
    alert_description: String(alertInfo.alertDescription),
    alert_level: String(alertInfo.alertLevel)
};

// Formato recomendado para influxdb out:
// [fields, tags]
msg.payload = [fields, tags];

// Timestamp en milisegundos
msg.timestamp = new Date(data.timestamp).getTime();

return msg;
